const data = $input.first().json;

const timeZone = 'Asia/Kolkata';

const dateFormatter = new Intl.DateTimeFormat('en-CA', {
  timeZone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
});

const today = dateFormatter.format(new Date());

const todayForecasts = data.list.filter(item => {
  const forecastDate = dateFormatter.format(new Date(item.dt * 1000));
  return forecastDate === today;
});

const rainConditions = ['Rain', 'Drizzle', 'Thunderstorm'];

const rainExpected = todayForecasts.some(item =>
  rainConditions.includes(item.weather?.[0]?.main)
);

const firstForecast = todayForecasts[0];

return [
  {
    json: {
      city: data.city?.name,
      country: data.city?.country,

      rainExpected,

      condition: firstForecast?.weather?.[0]?.description,

      temp: firstForecast?.main?.temp,
      feels_like: firstForecast?.main?.feels_like,

      temp_min: Math.min(
        ...todayForecasts.map(item => item.main.temp_min)
      ),

      temp_max: Math.max(
        ...todayForecasts.map(item => item.main.temp_max)
      ),

      humidity: firstForecast?.main?.humidity,
      pressure: firstForecast?.main?.pressure,

      wind_speed: firstForecast?.wind?.speed,
      cloudiness: firstForecast?.clouds?.all
    }
  }
];
